import { Component, Element, Event, EventEmitter, Host, Prop, h } from '@stencil/core';
import { Border, ItemSize } from '../../types';

/**
 * @slot start - slot for the content of the start side of the item
 * @slot default - default slot for the content of the item
 * @slot end - slot for the content of the end side of the item
 */
@Component({
  tag: 'groupui-item',
  styleUrl: 'item.scss',
  shadow: true,
})
export class Item {
  /**
   * sets the item padding size around the content
   */
  @Prop({ reflect: true }) readonly size: ItemSize = 'm';

  /**
   * sets an indentation on the item content
   */
  @Prop({ reflect: true }) readonly indentation: boolean;

  /**
   * sets the border
   */
  @Prop({ reflect: true }) readonly border: Border = 'bottom';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        <slot name="start" />
        <slot></slot>
        <slot name="end" />
      </Host>
    );
  }
}
